package com.example.starter.ros.domain;

/**
 * ROS 2 风格生命周期状态。
 *
 * <p>合法相邻迁移：
 * <ul>
 *     <li>{@code UNCONFIGURED -> INACTIVE}（configure）</li>
 *     <li>{@code INACTIVE -> ACTIVE}（activate）</li>
 *     <li>{@code ACTIVE -> INACTIVE}（deactivate）</li>
 *     <li>{@code INACTIVE -> UNCONFIGURED}（cleanup）</li>
 *     <li>任意非终结状态 {@code -> FINALIZED}（shutdown）</li>
 * </ul>
 */
public enum LifecycleState {
    UNCONFIGURED,
    INACTIVE,
    ACTIVE,
    FINALIZED;

    /**
     * 判断目标状态是否为当前状态的合法相邻迁移。
     *
     * @param target 目标状态
     * @return 合法返回 true，跳级/回环等非法迁移返回 false
     */
    public boolean canTransitionTo(LifecycleState target) {
        return switch (this) {
            case UNCONFIGURED -> target == INACTIVE || target == FINALIZED;
            case INACTIVE -> target == ACTIVE || target == UNCONFIGURED || target == FINALIZED;
            case ACTIVE -> target == INACTIVE || target == FINALIZED;
            case FINALIZED -> false;
        };
    }
}

package com.example.starter.ros.domain;

/**
 * 节点可声明的 ROS 2 资源类别。
 * 仅 {@link #SERVICE} 与 {@link #ACTION} 在存活节点间同名互斥；{@link #TOPIC} 允许多节点共享。
 */
public enum ResourceCategory {
    TOPIC,
    SERVICE,
    ACTION;

    /**
     * 解析资源类别字符串，大小写不敏感。
     *
     * @param raw 原始值
     * @return 枚举值
     * @throws IllegalArgumentException 未知类别
     */
    public static ResourceCategory from(String raw) {
        if (raw == null) {
            throw new IllegalArgumentException("resource category must not be null");
        }
        return ResourceCategory.valueOf(raw.trim().toUpperCase());
    }

    /**
     * 该类别是否在存活节点范围内同名互斥。
     *
     * @return Service/Action 返回 true
     */
    public boolean isExclusive() {
        return this == SERVICE || this == ACTION;
    }
}

package com.example.starter.ros.domain;

/**
 * 注册中心业务错误码，与 HTTP 状态码共同区分不同失败语义。
 */
public enum RegistryErrorCode {
    /** 请求参数校验失败 */
    VALIDATION_ERROR(400),
    /** 节点不存在 */
    NODE_NOT_FOUND(404),
    /** nodeId 重复注册，或崩溃/终结节点不允许该操作 */
    NODE_ALREADY_REGISTERED(409),
    /** 节点已终结（FINALIZED），不允许再迁移 */
    NODE_FINALIZED(410),
    /** 节点已异常退出（alive=0），不允许业务操作 */
    NODE_CRASHED(410),
    /** Service/Action 同名互斥冲突 */
    RESOURCE_CONFLICT(409),
    /** 非法相邻生命周期迁移 */
    ILLEGAL_TRANSITION(422),
    /** 乐观版本冲突 */
    VERSION_CONFLICT(409),
    /** 同一 requestId 异参重放 */
    IDEMPOTENCY_PARAM_MISMATCH(409),
    /** 同 requestId 并发请求仍在处理中，重放等待超时 */
    IDEMPOTENCY_INFLIGHT_TIMEOUT(409),
    /** 检查点不存在或已存在等检查点错误 */
    CHECKPOINT_ERROR(409);

    private final int httpStatus;

    RegistryErrorCode(int httpStatus) {
        this.httpStatus = httpStatus;
    }

    public int httpStatus() {
        return httpStatus;
    }
}

