@Override
public NodeView register(RegisterNodeRequest request) {
    List<ParsedResource> parsed = parseResources(request.resources());
    String paramsHash = ParamsHasher.sha256(normalizeRegister(request));

    // 对请求涉及的互斥资源名按名称取段锁并排序，避免死锁；不同名称仍可完全并发
    List<Object> locks = parsed.stream()
            .filter(r -> r.category().isExclusive())
            .map(r -> r.category().name() + "#" + r.fqn())
            .distinct()
            .sorted()
            .map(key -> nameLocks.computeIfAbsent(key, k -> new Object()))
            .toList();
    for (Object lock : locks) {
        //noinspection SynchronizationOnLocalVariableOrMethodParameter
        synchronized (lock) {
            // 在锁内重新排序列表语义：统一在最外层逐个加锁
        }
    }
    // 逐个加锁需保持有序，上面仅占位；真正的加锁在 runWithLocks 中完成
    return runWithNameLocks(locks, () ->
            executeIdempotent(request.requestId(), KIND_REGISTER, paramsHash, request.nodeId(),
                    NodeView.class, 201, () -> doRegister(request, parsed)));
}

